ALTER TABLE "Asset" ADD COLUMN "archivedAt" TIMESTAMP(3);
ALTER TABLE "Finding" ADD COLUMN "readAt" TIMESTAMP(3), ADD COLUMN "relatedRiskId" TEXT;
ALTER TABLE "Incident" ADD COLUMN "type" TEXT NOT NULL DEFAULT 'OTHER', ADD COLUMN "assetIds" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], ADD COLUMN "taskIds" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], ADD COLUMN "remainingRisks" TEXT NOT NULL DEFAULT '';
ALTER TABLE "Task" ADD COLUMN "batchId" TEXT, ADD COLUMN "notBefore" TIMESTAMP(3), ADD COLUMN "windowEnd" TIMESTAMP(3), ADD COLUMN "rollbackOf" TEXT;
CREATE TABLE "Setting" ("key" TEXT PRIMARY KEY,"value" JSONB NOT NULL,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Notification" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"title" TEXT NOT NULL,"resource" TEXT NOT NULL,"resourceId" TEXT,"readAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "Notification_userId_createdAt_idx" ON "Notification"("userId","createdAt");
CREATE TABLE "ImportBatch" ("id" TEXT PRIMARY KEY,"actor" TEXT NOT NULL,"status" TEXT NOT NULL,"items" JSONB NOT NULL,"result" JSONB,"error" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "TaskBatch" ("id" TEXT PRIMARY KEY,"title" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'PENDING',"stopOnFailure" BOOLEAN NOT NULL DEFAULT true,"createdBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
